contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory tos, uint[] memory v) public {
        require(tos.length > 0);
        require(tos.length == v.length);

        bool reverted;
        bool ret;
        try c.transfer(from, caddress, tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
        }

        bool calleeFailed;
        if (caddress.code.length > 0) {
            bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
            for (uint i = 0; i < tos.length; i++) {
                (bool s,) = caddress.call(abi.encodeWithSelector(id, from, tos[i], v[i]));
                if (!s) {
                    calleeFailed = true;
                    break;
                }
            }
        } else {
            calleeFailed = true;
        }

        assert(reverted == calleeFailed && (reverted || ret));
    }

    receive() external payable {}
}

